```openscad
// Cuvette stand for 4 standard 1 cm spectrophotometer cuvettes
// Units: mm. Print orientation: base on XY plane, builds +Z.

// ---- Block ----
block_x = 84;      // block length (X)
block_y = 30;      // block width (Y)
block_h = 25;      // block height (Z)

// ---- Pockets ----
n_pockets      = 4;     // number of cuvette pockets
pocket_w       = 12.8;  // pocket size in X and Y (square)
pocket_depth   = 22;    // pocket depth from top face
pocket_pitch   = 17.8;  // centre-to-centre spacing along X
floor_t        = block_h - pocket_depth; // remaining floor = 3 mm

// ---- Misc ----
eps = 0.5;   // overshoot for clean boolean cuts
$fn = 64;

difference() {
    // Main block, centred in X/Y, sitting on z = 0
    translate([-block_x/2, -block_y/2, 0])
        cube([block_x, block_y, block_h]);

    // Row of square pockets, centred on the block
    for (i = [0 : n_pockets - 1]) {
        px = (i - (n_pockets - 1)/2) * pocket_pitch;
        translate([px - pocket_w/2, -pocket_w/2, floor_t])
            cube([pocket_w, pocket_w, pocket_depth + eps]);
    }
}
```

