// Stand for 5 standard 1 cm spectrophotometer cuvettes
// Print orientation: base on XY plane, pockets open upward (+Z)

// ---------------- Block ----------------
block_x = 102;      // block length along X (mm)
block_y = 26;       // block width along Y (mm)
block_z = 32;       // block height (mm)

// ---------------- Pockets ----------------
pocket_count = 5;    // number of cuvette pockets
pocket_w     = 13;   // pocket size in X (mm)
pocket_d     = 13;   // pocket size in Y (mm)
pocket_depth = 27;   // pocket depth from top face (mm)
pocket_pitch = 19;   // centre-to-centre spacing along X (mm)

// ---------------- Derived ----------------
floor_t = block_z - pocket_depth;   // material below pockets (5 mm)
eps     = 0.5;                      // overshoot for clean cuts (mm)
row_start_x = -(pocket_count - 1) * pocket_pitch / 2;  // first pocket centre X

difference() {
    // Main block, centred in X/Y, standing on z = 0
    translate([-block_x / 2, -block_y / 2, 0])
        cube([block_x, block_y, block_z]);

    // Row of square pockets opened from the top face
    for (i = [0 : pocket_count - 1]) {
        translate([row_start_x + i * pocket_pitch - pocket_w / 2,
                   -pocket_d / 2,
                   floor_t])
            cube([pocket_w, pocket_d, pocket_depth + eps]);
    }
}
