```openscad
// Stand for 6 standard 1 cm spectrophotometer cuvettes
// Print orientation: base on XY plane (z = 0), pockets open upward (+Z)

// ---- Block dimensions ----
block_x = 128;      // block length along X
block_y = 30;       // block width along Y
block_z = 30;       // block height

// ---- Pocket dimensions ----
pocket_w     = 12.8;   // pocket size in X and Y (square)
pocket_depth = 25;     // pocket depth from top face
pocket_count = 6;      // number of pockets
pocket_pitch = 19.8;   // centre-to-centre spacing along X

// ---- Cutting overshoot ----
eps = 0.5;             // extension past the top face to avoid coplanar faces

// Derived
row_length  = (pocket_count - 1) * pocket_pitch;  // span between end pocket centres
pocket_floor = block_z - pocket_depth;           // floor height (5 mm above bottom)

difference() {
    // Main block, centred in X and Y, standing on z = 0
    translate([-block_x / 2, -block_y / 2, 0])
        cube([block_x, block_y, block_z]);

    // Row of square cuvette pockets, centred on the block
    for (i = [0 : pocket_count - 1]) {
        translate([-row_length / 2 + i * pocket_pitch - pocket_w / 2,
                   -pocket_w / 2,
                   pocket_floor])
            cube([pocket_w, pocket_w, pocket_depth + eps]);
    }
}
