```openscad
// Horizontal pipette rest
$fn = 96;

// --- Dimensions (mm) ---
base_len     = 160;  // base plate length (X)
base_wid     = 40;   // base plate width (Y)
base_thk     = 6;    // base plate thickness (Z)
upright_thk  = 8;    // upright block thickness (X)
upright_h    = 30;   // upright block height from z = 0
cradle_r     = 8;    // semicircular cradle notch radius
eps          = 0.5;  // overcut for clean differences

union() {
    // Base plate
    translate([-base_len/2, -base_wid/2, 0])
        cube([base_len, base_wid, base_thk]);

    // Uprights, flush with each end, with cradle notches
    for (s = [-1, 1]) {
        x0 = (s < 0) ? -base_len/2 : base_len/2 - upright_thk;
        difference() {
            translate([x0, -base_wid/2, 0])
                cube([upright_thk, base_wid, upright_h]);
            // Semicircular notch, centre at y = 0, z = upright_h, axis along X
            translate([x0 - eps, 0, upright_h])
                rotate([0, 90, 0])
                    cylinder(r = cradle_r, h = upright_thk + 2*eps);
        }
    }
}
