```openscad
// Horizontal pipette rest
// Print orientation: base plate on bed (z = 0), uprights build upward.

$fn = 96;

// ---- Dimensions (mm) ----
base_len      = 160;   // base plate length (X)
base_w        = 35;    // base plate width (Y)
base_t        = 4;     // base plate thickness (Z)

upright_t     = 12;    // upright block thickness (X)
upright_h     = 40;    // upright height from bed (Z)

cradle_r      = 10;    // semicircular cradle radius
cradle_z      = 40;    // cradle centre height (top edge of upright)

eps           = 0.5;   // overcut for clean differences

// ---- Model ----
difference() {
    union() {
        // Base plate
        translate([-base_len/2, -base_w/2, 0])
            cube([base_len, base_w, base_t]);

        // Uprights, flush with each end
        for (sx = [-1, 1])
            translate([sx > 0 ? base_len/2 - upright_t : -base_len/2, -base_w/2, 0])
                cube([upright_t, base_w, upright_h]);
    }

    // Cradle notches cut through each upright along X
    for (sx = [-1, 1])
        translate([sx * (base_len/2 - upright_t/2), 0, cradle_z])
            rotate([0, 90, 0])
                cylinder(r = cradle_r, h = upright_t + 2*eps, center = true);
}
