```openscad
// Horizontal pipette rest
// Print orientation: base plate on bed (z = 0), uprights build upward (+Z)

$fn = 96;

// ---- Base plate ----
base_len   = 140;   // plate length along X (mm)
base_wid   = 30;    // plate width along Y (mm)
base_thk   = 4;     // plate thickness along Z (mm)

// ---- End uprights ----
up_thk     = 10;    // upright thickness along X (mm)
up_wid     = base_wid; // upright width along Y (same as plate)
up_h       = 35;    // upright top height, from z = 0 (mm)

// ---- Cradle notch ----
notch_r    = 8;     // semicircular notch radius (mm)
notch_y    = 0;     // notch centre Y (mm)
notch_z    = up_h;  // notch centre Z, on top edge (mm)

// ---- Cutting overlap ----
eps        = 0.5;   // extension past cut faces (mm)

module upright(x0) {
    difference() {
        translate([x0, -up_wid/2, 0])
            cube([up_thk, up_wid, up_h]);
        // cradle notch running through upright along X
        translate([x0 - eps, notch_y, notch_z])
            rotate([0, 90, 0])
                cylinder(r = notch_r, h = up_thk + 2*eps);
    }
}

union() {
    // base plate
    translate([-base_len/2, -base_wid/2, 0])
        cube([base_len, base_wid, base_thk]);

    // uprights flush with each end
    for (x0 = [-base_len/2, base_len/2 - up_thk])
        upright(x0);
}
