```openscad
// Horizontal pipette rest
// Units: mm. Print orientation: base plate on bed (z = 0), uprights build +Z.

$fn = 96;

// ---- Base plate ----
plate_len   = 140;   // plate length along X
plate_wid   = 40;    // plate width along Y
plate_thk   = 5;     // plate thickness along Z

// ---- Uprights ----
upright_thk = 10;    // upright thickness along X
upright_h   = 30;    // upright top height (z = 0 to 30)

// ---- Cradle notch ----
notch_r     = 8;     // semicircular notch radius, centre at y = 0, z = upright_h

// ---- Cutting overlap ----
eps         = 0.5;   // extension of cutters past faces

module base_plate() {
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);
}

module upright(x0) {
    // x0 = lower X bound of the upright
    difference() {
        translate([x0, -plate_wid/2, 0])
            cube([upright_thk, plate_wid, upright_h]);
        // Semicircular cradle notch running along X
        translate([x0 - eps, 0, upright_h])
            rotate([0, 90, 0])
                cylinder(r = notch_r, h = upright_thk + 2*eps);
    }
}

union() {
    base_plate();
    // Uprights flush with each end of the plate
    for (x0 = [-plate_len/2, plate_len/2 - upright_thk])
        upright(x0);
}
