        // Base plate, centred on origin in X and Y
        translate([-base_len/2, -base_wid/2, 0])
            cube([base_len, base_wid, base_thk]);

        // Uprights, flush with each end of the plate
        for (sx = [-1, 1])
            translate([sx > 0 ? base_len/2 - up_thk : -base_len/2,
                       -base_wid/2, 0])
                cube([up_thk, base_wid, up_h]);
    }

    // Cradle notches: cylinder axis along X, centre at y = 0, z = 30
    for (sx = [-1, 1])
        translate([sx * (base_len/2 - up_thk/2), 0, notch_z])
            rotate([0, 90, 0])
                cylinder(r = notch_r, h = up_thk + 2*eps, center = true);
