// Bench mat for 2 Petri dishes (90 mm) - prevents sliding
// Print orientation: flat on bed, recesses facing up

// ---------- Parameters ----------
plate_x      = 212;   // plate length along X (mm)
plate_y      = 112;   // plate width along Y (mm)
plate_t      = 5;     // plate thickness (mm)

recess_d     = 92;    // recess diameter (mm)
recess_depth = 2;     // recess depth from top face (mm)
recess_n     = 2;     // number of recesses in the row
recess_pitch = 100;   // centre-to-centre spacing along X (mm)

eps          = 0.5;   // cutter overshoot past top face (mm)
$fn          = 128;   // circle resolution

// ---------- Model ----------
difference() {
    // Base plate, centred in X/Y, resting on z = 0
    translate([-plate_x / 2, -plate_y / 2, 0])
        cube([plate_x, plate_y, plate_t]);

    // Circular recesses in a single row along X, row centred on plate
    for (i = [0 : recess_n - 1]) {
        x = (i - (recess_n - 1) / 2) * recess_pitch;
        translate([x, 0, plate_t - recess_depth])
            cylinder(d = recess_d, h = recess_depth + eps);
    }
}
