```openscad
// Flat hex-cap wrench for reagent bottles
// Print flat on the bed: z = 0 to plate_t

// ---------------- Parameters ----------------
plate_t      = 8;     // plate thickness (Z)
head_d       = 55;    // round head diameter, centred on origin
handle_w     = 16;    // handle width (Y), centred on y = 0
handle_x0    = 0;     // handle start (X)
handle_x1    = 100;   // handle end (X)
hex_af       = 24;    // hexagon size across flats
cut_ext      = 1;     // extra length for cutters past faces

hex_r = (hex_af / 2) / cos(30);  // hexagon circumradius (vertex distance)

$fn = 128;

// ---------------- Model ----------------
difference() {
    union() {
        // Round head
        cylinder(d = head_d, h = plate_t);

        // Straight handle
        translate([handle_x0, -handle_w / 2, 0])
            cube([handle_x1 - handle_x0, handle_w, plate_t]);
    }

    // Hexagonal through-hole; circle($fn=6) puts vertices on the X axis,
    // so two flats lie parallel to X (at y = +/- hex_af/2)
    translate([0, 0, -cut_ext])
        linear_extrude(height = plate_t + 2 * cut_ext)
            circle(r = hex_r, $fn = 6);
}
```

