// Flat hex-cap wrench for reagent bottles
// Print orientation: lying flat on the bed, z = 0 to plate_t

$fn = 96;

// ---- Dimensions (mm) ----
plate_t      = 8;     // plate thickness (Z)
head_d       = 45;    // round head diameter, centred on origin
handle_w     = 16;    // handle width (Y), centred on y = 0
handle_x0    = 0;     // handle start (X)
handle_x1    = 100;   // handle end (X)
hex_af       = 30;    // hex hole size across flats
cut_extra    = 0.5;   // overshoot for clean boolean cuts

// Derived: hex circumradius (centre to vertex)
hex_r = (hex_af / 2) / cos(30);

difference() {
    // Solid body: head disc + handle bar
    union() {
        cylinder(d = head_d, h = plate_t, $fn = 128);
        translate([handle_x0, -handle_w / 2, 0])
            cube([handle_x1 - handle_x0, handle_w, plate_t]);
    }

    // Hexagonal hole: vertices on X axis -> two flats parallel to X
    translate([0, 0, -cut_extra])
        linear_extrude(height = plate_t + 2 * cut_extra)
            circle(r = hex_r, $fn = 6);
}
