// Hex key organiser block
// Print orientation: block stands on its base at z = 0, pockets open upward.

// ---------------- Block dimensions ----------------
block_len   = 72;    // block length along X (mm)
block_wid   = 20;    // block width along Y (mm)
block_ht    = 30;    // block height along Z (mm)

// ---------------- Pocket parameters ----------------
pocket_depth = 15;                      // depth of each hex pocket from top face (mm)
pocket_pitch = 12;                      // centre-to-centre spacing along X (mm)
pocket_af    = [3.4, 4.4, 5.4, 6.4, 8.4]; // across-flats sizes, -X to +X (mm)
n_pockets    = len(pocket_af);          // number of pockets

// ---------------- Misc ----------------
eps = 0.5;          // overcut past faces to avoid coplanar surfaces (mm)

// Across-flats -> circumradius for a regular hexagon
function hex_r(af) = af / sqrt(3);

difference() {
    // Main block, centred in X and Y, sitting on z = 0
    translate([-block_len/2, -block_wid/2, 0])
        cube([block_len, block_wid, block_ht]);

    // Hexagonal pockets along y = 0, centred on the block
    for (i = [0 : n_pockets - 1]) {
        x = (i - (n_pockets - 1) / 2) * pocket_pitch;
        translate([x, 0, block_ht - pocket_depth])
            // cylinder($fn=6) has vertices on X (flats parallel to Y);
            // rotate 30 deg so two flats are parallel to the X axis
            rotate([0, 0, 30])
                cylinder(h = pocket_depth + eps,
                         r = hex_r(pocket_af[i]),
                         $fn = 6);
    }
}
