// Flat spacer ring with bolt-circle holes
// Units: mm

$fn = 128;

// --- Ring dimensions ---
ring_thickness = 4;     // ring height (Z)
outer_d        = 90;    // outer diameter
inner_d        = 60;    // inner diameter (bore)

