    cylinder(d = outer_d, h = ring_thickness);

    // Central bore
    translate([0, 0, -eps])
        cylinder(d = inner_d, h = ring_thickness + 2 * eps);

    // Bolt-circle holes
    for (i = [0 : hole_count - 1]) {
        a = start_angle + i * 360 / hole_count;
        translate([bolt_circle_d / 2 * cos(a), bolt_circle_d / 2 * sin(a), -eps])
            cylinder(d = hole_d, h = ring_thickness + 2 * eps, $fn = 64);
    }
}
