// Glassware drying board - base plate with a 5 x 4 grid of vertical pegs

// ---- Base plate ----
plate_x      = 144;   // plate length along X (mm)
plate_y      = 114;   // plate width along Y (mm)
plate_t      = 6;     // plate thickness (mm), z = 0 to 6

// ---- Pegs ----
peg_d        = 6;     // peg diameter (mm)
peg_top_z    = 36;    // top of pegs (mm)
peg_h        = peg_top_z - plate_t;  // peg height above plate (30 mm)
peg_nx       = 5;     // number of pegs along X
peg_ny       = 4;     // number of pegs along Y
peg_pitch    = 30;    // centre-to-centre spacing in X and Y (mm)
overlap      = 0.01;  // small overlap so pegs fuse into the plate

$fn = 64;             // curve resolution

// Grid offsets so the grid is centred on the plate
grid_x0 = -(peg_nx - 1) * peg_pitch / 2;
grid_y0 = -(peg_ny - 1) * peg_pitch / 2;

union() {
    // Base plate, centred in XY, resting on z = 0
    translate([-plate_x / 2, -plate_y / 2, 0])
        cube([plate_x, plate_y, plate_t]);

    // Peg grid
