// Adjustable shim plate with two rounded-end bolt slots
// Units: mm. Print orientation: flat on bed, z = 0 at bottom.

// ---------------- Parameters ----------------
plate_length   = 50;    // overall plate length (X)
plate_width    = 20;    // overall plate width (Y)
plate_thick    = 4;     // plate thickness (Z)

