slot_centre_y  = 0;     // slot centre Y position

eps            = 0.5;   // cutter overshoot past faces
$fn            = 96;    // curve resolution

// Derived
slot_r      = slot_width / 2;              // end radius
slot_c2c    = slot_length - slot_width;    // distance between end-arc centres

// ---------------- Modules ----------------
module slot_cutter() {
    // Stadium-shaped through-cutter, centred on origin, running along X
    translate([0, 0, -eps])
        hull() {
            for (sx = [-1, 1])
                translate([sx * slot_c2c / 2, 0, 0])
                    cylinder(r = slot_r, h = plate_thick + 2 * eps, $fn = $fn);
        }
}

// ---------------- Part ----------------
difference() {
    translate([-plate_length / 2, -plate_width / 2, 0])
        cube([plate_length, plate_width, plate_thick]);

    for (x = slot_centres_x)
        translate([x, slot_centre_y, 0])
            slot_cutter();
}
