// Microplate riser
// Units: mm. Print orientation: legs on bed (z = 0), plate on top.

// ---- Top plate ----
plate_x      = 130;   // plate length (X)
plate_y      = 95;    // plate width (Y)
plate_t      = 6;     // plate thickness
plate_top_z  = 30;    // height of plate top face

// ---- Legs ----
leg_size     = 12;    // square leg side length (X and Y)

// ---- Central window ----
window_x     = 86;    // window length (X)
window_y     = 61;    // window width (Y)

// ---- Misc ----
eps          = 0.5;   // cutter overshoot past cut faces
overlap      = 0.01;  // tiny leg/plate overlap for a clean union
$fn          = 64;

// Derived
plate_bot_z  = plate_top_z - plate_t;   // underside of plate (z = 24)
leg_h        = plate_bot_z;             // legs run z = 0 to underside

module top_plate() {
    difference() {
        translate([-plate_x/2, -plate_y/2, plate_bot_z])
            cube([plate_x, plate_y, plate_t]);
        // Central rectangular window, through the plate
        translate([-window_x/2, -window_y/2, plate_bot_z - eps])
            cube([window_x, window_y, plate_t + 2*eps]);
    }
}

module legs() {
    for (sx = [-1, 1], sy = [-1, 1]) {
        // Corner leg, flush with plate outer edges
        translate([sx > 0 ? plate_x/2 - leg_size : -plate_x/2,
                   sy > 0 ? plate_y/2 - leg_size : -plate_y/2,
                   0])
            cube([leg_size, leg_size, leg_h + overlap]);
    }
}

union() {
    top_plate();
    legs();
}
