top_z        = 40;    // height of the top face of the plate
leg_size     = 12;    // square leg cross-section (X and Y)
window_x     = 116;   // central window length (X)
window_y     = 46;    // central window width (Y)
eps          = 0.5;   // overcut for clean boolean differences
overlap      = 0.01;  // small overlap so legs fuse with the plate

// ---- Derived ----
plate_bot_z  = top_z - plate_t;   // underside of the top plate
leg_h        = plate_bot_z;       // legs run from z = 0 to the underside

module top_plate() {
    difference() {
        translate([-plate_x/2, -plate_y/2, plate_bot_z])
            cube([plate_x, plate_y, plate_t]);
        // central window, overcut past top and bottom faces
        translate([-window_x/2, -window_y/2, plate_bot_z - eps])
            cube([window_x, window_y, plate_t + 2*eps]);
    }
}

module legs() {
    for (sx = [-1, 1], sy = [-1, 1]) {
        // each leg flush with the outer edges of the plate
        translate([sx > 0 ? plate_x/2 - leg_size : -plate_x/2,
                   sy > 0 ? plate_y/2 - leg_size : -plate_y/2,
                   0])
            cube([leg_size, leg_size, leg_h + overlap]);
    }
}

union() {
    top_plate();
    legs();
}
