// Wall mounting strip with countersunk screw holes
// Print orientation: flat on bed, countersinks facing up (+Z)

$fn = 64;

// ---- Bar dimensions ----
bar_length    = 224;   // X length of strip
bar_width     = 24;    // Y width of strip
bar_thick     = 4;     // Z thickness of strip

