hole_pitch    = 50;    // centre-to-centre spacing along X
hole_d        = 3.4;   // through-hole diameter
csk_d         = 6.5;   // countersink diameter at top surface
csk_angle     = 90;    // countersink included angle (degrees)

// ---- Derived values ----
csk_depth     = (csk_d - hole_d) / 2 / tan(csk_angle / 2); // depth of cone
eps           = 0.5;   // overshoot for clean boolean cuts
csk_top_d     = csk_d + 2 * eps * tan(csk_angle / 2);      // cone diameter at overshoot height
first_x       = -(hole_count - 1) * hole_pitch / 2;        // X of first hole

difference() {
    // Flat bar
    translate([-bar_length / 2, -bar_width / 2, 0])
        cube([bar_length, bar_width, bar_thick]);

    // Screw holes
    for (i = [0 : hole_count - 1]) {
        translate([first_x + i * hole_pitch, 0, 0]) {
            // Through-hole
            translate([0, 0, -eps])
                cylinder(d = hole_d, h = bar_thick + 2 * eps);

            // 90-degree countersink, extended above top face
            translate([0, 0, bar_thick - csk_depth])
                cylinder(d1 = hole_d, d2 = csk_top_d, h = csk_depth + eps);
        }
    }
}
