$fn             = 96;    // facet count for round features

// ---------------- Derived values ----------------
// Countersink depth for given included angle
csk_depth = ((csk_d - hole_d) / 2) / tan(csk_angle / 2);   // 2.75 mm for 90 deg
// Diameter of cone extended eps above the top face (keeps same angle)
csk_d_ext = csk_d + 2 * eps * tan(csk_angle / 2);

