    translate([-bar_length / 2, -bar_width / 2, 0])
        cube([bar_length, bar_width, bar_thickness]);

    // Screw holes, centred on the bar along X at y = 0
    for (i = [0 : hole_count - 1]) {
        x = -hole_spacing * (hole_count - 1) / 2 + i * hole_spacing;
        translate([x, 0, 0]) {
            // Through-hole
            translate([0, 0, -eps])
                cylinder(h = bar_thickness + 2 * eps, d = hole_d);

            // 90-degree countersink on top face
            translate([0, 0, bar_thickness - csk_depth])
                cylinder(h = csk_depth + eps, d1 = hole_d, d2 = csk_d_ext);
        }
    }
}
